import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"RoboTwin 2.0: A Scalable Data Generator and Benchmark with Strong Domain Randomization for Robust Bimanual Robotic Manipulation","description":"","frontmatter":{"title":"RoboTwin 2.0: A Scalable Data Generator and Benchmark with Strong Domain Randomization for Robust Bimanual Robotic Manipulation","arxiv":"2506.18088","date":"2025-06-22","authors":"Tianxing Chen, Zanxin Chen, Baijun Chen, Zijian Cai, Yibin Liu, Zixuan Li, Qiwei Liang, Xianliang Lin, Yiheng Ge, et al. (通讯 Ping Luo, Yao Mu)","categories":"cs.RO, cs.AI, cs.CL, cs.CV, cs.MA","topics":"具身智能, 仿真数据生成, 域随机化与双臂操作","outline":[2,2]},"headers":[],"relativePath":"papers/2506.18088.md","filePath":"papers/2506.18088.md","lastUpdated":null}'),l={name:"papers/2506.18088.md"};function e(i,s,r,m,c,o){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="robotwin-2-0-a-scalable-data-generator-and-benchmark-with-strong-domain-randomization-for-robust-bimanual-robotic-manipulation" tabindex="-1">RoboTwin 2.0: A Scalable Data Generator and Benchmark with Strong Domain Randomization for Robust Bimanual Robotic Manipulation <a class="header-anchor" href="#robotwin-2-0-a-scalable-data-generator-and-benchmark-with-strong-domain-randomization-for-robust-bimanual-robotic-manipulation" aria-label="Permalink to &quot;RoboTwin 2.0: A Scalable Data Generator and Benchmark with Strong Domain Randomization for Robust Bimanual Robotic Manipulation&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2506.18088" target="_blank" rel="noreferrer">2506.18088</a></td></tr><tr><td><strong>提交日期</strong></td><td>2025-06-22</td></tr><tr><td><strong>作者</strong></td><td>Tianxing Chen, Zanxin Chen, Baijun Chen, Zijian Cai, Yibin Liu, Zixuan Li, Qiwei Liang, Xianliang Lin, Yiheng Ge, et al.（共 26 人，通讯 Ping Luo、Yao Mu）</td></tr><tr><td><strong>分类</strong></td><td>cs.RO, cs.AI, cs.CL, cs.CV, cs.MA</td></tr><tr><td><strong>一句话</strong></td><td>用 MLLM 写任务代码 + VLM 看仿真回放做闭环修复，自动产出双臂专家轨迹，再沿杂物/光照/背景/桌高/语言五轴做域随机化，形成 50 任务 5 本体 10 万条轨迹的数据生成器与基准。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/video-for-embodied-ai">视频生成赋能具身智能</a></p></blockquote><div class="tip custom-block"><p class="custom-block-title">版本说明</p><p>本文 v1 提交于 2025-06-22，最新为 <strong>v2</strong>（2025-08-27），本解读基于 v2 全文。</p></div><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>双臂操作（协作装配、工具使用、物体交接）需要的数据同时要高质量、多样、且大规模，而真机遥操作在这三个维度上都扩不动。仿真合成是公认的替代方案，但论文指出现有流水线有三个具体缺口。</p><p>第一，<strong>缺自动质量控制</strong>。没有专家级验证闭环时，生成的轨迹里混着执行失败与次优抓取，这些样本会直接污染策略学习。第二，<strong>域随机化太表面</strong>，场景过于干净同质，缺少杂物、光照变化与含糊的语言指令，而这些恰恰是 sim-to-real 的关键因素。第三，<strong>忽略跨本体差异</strong>——低自由度平台（Piper）因为灵巧性受限往往只能侧向抓，高自由度臂（Franka）可以自上而下精抓；同一个任务在不同本体上的可行抓取姿态完全不同，而现有合成数据几乎不编码这种本体相关的 affordance。</p><p>这篇工作要解决的就是这三条，且它给出的证据里有一个特别有说服力的负面观察：把<strong>干净的</strong>仿真数据拿去微调 RDT 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，平均成功率几乎不动甚至下降。这说明「仿真数据没用」的通常解释（Real-to-Sim 差距）站不住脚——差距不在渲染，而在多样性。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p>仿真平台各有侧重：SAPIEN 提供 2300+ 铰接物体，ManiSkill2 提供百万级演示，Meta-World / CALVIN / LIBERO / RoboVerse 分别面向多任务、语言条件、终身学习与域随机化，RoboCasa 提供大规模人类演示但缺自动化且不面向双臂。真机大数据集（AgiBot World、RoboMIND、Open X-Embodiment、Bridge）在规模上更强，但采集成本是线性的。</p><p>MLLM 写机器人代码这条线（GenSim2、RoboGen、RoboCodex）已经证明语言模型能产出可执行的任务程序，但论文指出它们要么依赖很强的人工先验，要么在程序合成阶段没有闭环反馈，因此在多样或动态环境里不稳定；而且大多局限于基本的 pick-and-place，做不出复杂的双臂协作行为。</p><p>域随机化本身是老工具（Tobin 等 2017 起），论文对它的批评很具体：既有工作<strong>孤立地</strong>施加随机化，缺少双向的数字孪生反馈——也就是说没有一个机制去判断随机化之后的轨迹到底还成不成立。</p><p>RoboTwin 1.0 是本文的直接前身，它把真机演示镜像成仿真副本用于双臂基准，但没有 LLM 驱动的反馈修复，也没有系统性的域随机化。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>从 1.0 到 2.0 的推理链可以这样还原。1.0 已经有了双臂仿真基准，但每加一个新任务都要人写代码；MLLM 写代码已经成熟，所以第一步是把任务程序合成交给模型。但一次性生成的代码成功率只有约 62%（本文的 R2.0 Vanilla 数字），所以需要修复循环。执行日志能告诉你「失败了」，却告诉不了你「为什么」——这是一个纯符号信号无法覆盖的诊断缺口。于是第二步是加一个 VLM 观察者，逐帧看回放、判断在哪一步失败、并推断失败是逻辑错、API 用错还是别的原因。</p><p>数据有了之后，第二个问题浮现：为什么用干净仿真数据训出来的策略在真机上不行？两个候选解释——渲染差距（Real-to-Sim）或多样性不足。作者用一个干净仿真数据的对照直接把第一个解释排除了。于是第三步是沿五个轴做随机化。</p><p>第三个问题来自跨本体：同一段代码在 Piper 上跑不通，因为它够不到自上而下的抓取姿态。解决方式不是给每个本体写一份代码，而是给<strong>物体</strong>标注多组候选抓取位姿与接近方向，让运动规划在里面挑一个可行的——这把本体差异从代码层挪到了资产层。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>仿真数据在真机上失效，通常被归咎于渲染不够真，但更可能的原因是场景不够乱。一个自动化的数据工厂需要三件事各就各位：让 MLLM 写代码并用 VLM 看着它改（质量），沿杂物/光照/背景/桌高/语言五轴随机化（多样性），把抓取姿态标在物体上而非写死在代码里（跨本体）。三者缺一，合成数据就只是把干净场景重复了一万遍。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以 Handover Block（双臂交接方块）为例。</p><p><strong>资产层：RoboTwin-OD。</strong> 147 类 731 个物体：534 个（111 类）由团队用 Rodin 平台做 RGB→3D 重建、再经凸分解与网格合并保证碰撞模型物理正确；153 个（27 类）来自 Objaverse，主要用于丰富干扰物；44 个（9 类）铰接物来自 SAPIEN PartNet-Mobility。每个物体自动生成 15 条语言描述（形状/纹理/功能/部件/粒度各异）并经人工核验，同时标注放置点、功能点、抓取点与抓取轴。纹理库的构造是：LLM 提示 + 网络爬取得到 1,000 条表面描述 → Stable Diffusion v2 每条生成 20 张 → 20,000 张经人工筛选留下 11,000 张。</p><p><strong>代码生成闭环。</strong> 任务用「名字 + 目标描述」定义。代码生成 agent 拿到通用 API 列表、示例函数调用与分层约束规范，产出 Python 程序。程序每轮在仿真里执行 <strong>10 次</strong>（吸收动力学、控制器与传感器噪声的随机性），系统输出结构化日志，标注每次的成败与失败原因（代码不可执行 / 左臂或右臂抓取失败 / 放置位置错）。与此同时 VLM 观察者逐帧看这 10 次回放，定位失败发生在哪一步，并推断根因。代码 agent 拿到「定量日志 + 定性诊断」两路反馈后改写程序，直到某一轮达标或连续 <strong>5 次</strong> 修复失败后终止。</p><p><strong>域随机化五轴。</strong> 杂物（从 RoboTwin-OD 采样干扰物，按放置标注做碰撞感知摆放，且排除与任务物体视觉或语义相似的干扰物以免产生歧义）；背景纹理（11,000 张库）；光照（颜色、类型、强度、位置在物理合理范围内随机）；桌面高度（实验中随机幅度到 3 cm）；语言指令（模板池 × 物体描述池组合采样，逐条轨迹独立采样）。</p><p><strong>本体自适应抓取。</strong> 每个物体标多组候选操作位姿，覆盖多个抓取轴与接近方向，再按各臂可达性做有偏的角度扰动，并行尝试运动规划。5 个本体：Aloha-AgileX、Piper、Franka、UR5、ARX-X5。</p><p><strong>产物。</strong> 50+ 双臂任务、5 个本体、10 万条以上预采集轨迹，外加一个 Easy（干净）/ Hard（随机化）两档的评测基准与在线排行榜。</p><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>本文无形式化数学推导，跳过。唯一的形式化是评测口径的定义：第 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6595em;"></span><span class="mord mathnormal">i</span></span></span></span> 个程序的成功率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.417em;vertical-align:-0.4358em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8451em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">M</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.9812em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.2029em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">M</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.4358em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">s</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mpunct mtight">,</span><span class="mord mathnormal mtight" style="margin-right:0.0572em;">j</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2861em;"><span></span></span></span></span></span></span></span></span></span>（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">M</span></span></span></span> 次执行），某任务在某系统变体下的最终成功率 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.8333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord text mtight"><span class="mord mtight">task</span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.3262em;vertical-align:-0.345em;"></span><span class="mord"><span class="mopen nulldelimiter"></span><span class="mfrac"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8451em;"><span style="top:-2.655em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span><span style="top:-3.23em;"><span class="pstrut" style="height:3em;"></span><span class="frac-line" style="border-bottom-width:0.04em;"></span></span><span style="top:-3.394em;"><span class="pstrut" style="height:3em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight">1</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.345em;"><span></span></span></span></span></span><span class="mclose nulldelimiter"></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mop"><span class="mop op-symbol small-op" style="position:relative;top:0em;">∑</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.9812em;"><span style="top:-2.4003em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">i</span><span class="mrel mtight">=</span><span class="mord mtight">1</span></span></span></span><span style="top:-3.2029em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight" style="margin-right:0.109em;">N</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2997em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0077em;">R</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:-0.0077em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathnormal" style="margin-right:0.109em;">N</span></span></span></span> 个候选程序）。读表时需要注意 ASR 是对全部候选程序求平均，而 Top5-ASR 只取每个任务最好的 5 个候选——后者才对应实际使用场景（挑一个好程序去批量采数据）。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：闭环反馈对代码生成有多大用？</strong> 在 1.0 与 2.0 都支持的 10 个任务子集上，ASR：R1.0 Vanilla 47.4% → +执行日志反馈 60.4% → +多模态反馈 63.9%；R2.0 Vanilla 62.1% → 66.7% → 71.3%。Top5-ASR 同向（R2.0 从 68.0% 到 78.6%）。收敛更快（MM FB 下 1.76 轮 vs 1.0 的 2.42 轮），token 更省（Vanilla 569.4 vs 1236.6）。摘要写的「10.9% 的代码生成成功率提升」<strong>无法从表 1 复原</strong>：最接近的是 R2.0 Vanilla→MM FB 的 +9.2（ASR）或 +10.6（Top5-ASR），也可能来自附录的逐任务表。</p><p><strong>问题二：本体自适应抓取值多少？</strong> 50 个任务 × 5 个本体的自动采数成功率：Aloha-AgileX 65.1→78.8、Piper <strong>2.4→25.1</strong>、ARX-X5 68.6→74.2，而高自由度的 Franka 67.3→67.2、UR5 57.6→57.1 实际上是<strong>略降</strong>（正文措辞是「largely unchanged」）。平均 52.2→60.5。正文把 Aloha-AgileX 的增益写成 13.5%，表里是 +13.7%。Piper 从 2.4% 起步说明 1.0 在该本体上基本不可用，这一项支配了平均值的抬升。</p><p><strong>问题三：域随机化是否真的带来鲁棒性？</strong> 先在 32 个任务 9,600 条轨迹上分别用干净与随机化两种设定预训 RDT 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，再在 5 个未见任务上各用 50 条干净演示单任务微调，最后全部在随机化条件下评测。平均成功率：ACT 2.0%、DP 0.0%、RDT 18.8%、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 22.5%、RDT+Clean <strong>14.6%</strong>、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>+Clean 24.9%、RDT+Rand 24.8%、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>+Rand 29.1%。</p><p>两处需要如实指出：其一，正文说干净数据带来的是「negligible improvements」，但 RDT+Clean 的 14.6% 实际上<strong>比不微调的 18.8% 低 4.2 点</strong>，是明确的下降而非持平。其二，随机化并非逐任务一致有效——Place Object Basket 上 RDT 从 17.0% 掉到 6.0%，Pick Dual Bottles 上 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 从 12.0% 掉到 7.0%，Move Can Pot 上 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>+Clean（35.0%）明显高于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>+Rand（22.0%）。相对增益 31.9%（RDT）与 29.3%（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>）是平均口径。</p><p><strong>问题四：真机 sim-to-real。</strong> COBOT-Magic 双臂 + RDT 骨干，4 个任务（Stack Bowls / Handover Block / Pick Bottle / Click Bell），三种训练设定（10 条干净真机演示 / 加 1,000 条随机化合成 / 纯 1,000 条合成），4 种测试配置（背景见过与否 × 是否杂乱）。四配置平均：仅真机 29.5 / 14.0 / 15.5 / 9.0；加合成 43.0 / 41.5 / 39.0 / 42.0；纯合成（只在未见背景两档评）36.5 / 29.5。绝对提升 +13.5 / +27.5 / +23.5 / +33.0，四档平均 +24.4 点。</p><p><strong>摘要里的 367% 与 228% 需要还原口径</strong>：<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">42.0</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">9.0</span><span class="mclose">)</span><span class="mord">/9.0</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">367%</span></span></span></span> 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">29.5</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord">9.0</span><span class="mclose">)</span><span class="mord">/9.0</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.8056em;vertical-align:-0.0556em;"></span><span class="mord">228%</span></span></span></span>，两者都取自<strong>最难的那一格</strong>（未见背景 + 杂乱，基线仅 9.0%），而不是平均。四配置平均的相对提升约为 143%。逐格看，16 个格子里有 2 个回退：Handover Block 见过背景 + 杂乱从 16.0% 降到 12.0%，Click Bell 见过背景 + 干净从 36.0% 降到 24.0%。另外零样本并非总是弱于少样本：Stack Bowls 未见背景 + 干净上零样本 60.0% &gt; 少样本 50.0%，Pick Bottle 未见背景 + 杂乱上 32.0% &gt; 28.0%。</p><p><strong>问题五：作为基准它区分度如何？</strong> 50 个任务、Aloha AgileX、每任务 50 条干净演示训练、100 次 rollout 评测。Easy/Hard 平均：RDT 34.5/13.7、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 46.4/16.3、ACT 29.7/1.7、DP 28.0/0.6、DP3 55.2/5.0。DP3 在 Easy 上最强（55.2）却在 Hard 上塌到 5.0，作者自己指出这部分源于仿真里的点云是完美的、背景分割是干净的。预训练 VLA 的相对保留率更高（RDT 保住 40%、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 35%），但绝对跌幅 20.8 与 30.1 点仍然很大。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>五句话版。</strong> RoboTwin 2.0 把双臂专家数据的生产自动化：MLLM 写任务代码，每轮跑 10 次仿真并由 VLM 逐帧诊断失败根因，最多 5 轮修复，ASR 从 62.1% 提到 71.3%。抓取姿态标在物体上而非写死在代码里，使低自由度本体的自动采数成功率大幅回升（Piper 2.4%→25.1%），高自由度本体则基本不变。沿杂物/背景/光照/桌高/语言五轴随机化后，预训数据让 RDT 与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 在随机化评测下相对提升约 30%，而用干净仿真数据微调几乎无效甚至更差——这直接排除了「Real-to-Sim 渲染差距」这一解释。真机上 10 条演示 + 1,000 条合成轨迹在四种配置下平均提升 24.4 个点，纯合成零样本在未见背景两档也有 20 点以上提升。50 任务基准显示所有策略从 Easy 到 Hard 都大幅退化，DP3 从 55.2 塌到 5.0。</p><p><strong>三句话版。</strong> 合成数据在真机上失效的主因是多样性不足而非渲染保真，本文用一个干净仿真数据的对照把这一点钉死了。自动化的关键是把「质量控制」交给 VLM 观察者、把「本体差异」交给物体级的抓取标注。代价是所有结论都建立在自家仿真器的评测上，且真机验证仅 4 个任务、单一平台。</p><p><strong>一句话版。</strong> 让 MLLM 写代码、VLM 挑错、随机化补多样性，把双臂专家数据变成可以按量产出的工业品。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的一条是：<strong>「训练时见过的随机化」与「真实世界里的分布偏移」是同一类东西。</strong> 全文的鲁棒性叙事都建立在这上面——五轴随机化的每一轴都是在仿真里按可控参数生成的（11,000 张由 Stable Diffusion 生成再人工筛的纹理、物理合理范围内的光照、3 cm 内的桌高、从模板池组合的语言），而真实世界的偏移包括反光材质、运动模糊、遮挡遮蔽、抓握滑移、控制延迟等根本不在这五轴上的因素。</p><p>论文提供的支持证据是真机表 4：加了合成数据后，越难的配置增益越大（未见背景 + 杂乱 +33.0 点）。这确实是强证据，但它测的恰好是<strong>与训练随机化同构</strong>的偏移——「未见背景」在仿真里就是换纹理，「杂乱」在仿真里就是加干扰物。也就是说，评测轴与随机化轴是一一对应的。</p><p>论文自己给的反向证据同样值得注意：基准表里所有策略从 Easy 到 Hard 都大幅退化（RDT −20.8、<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">π</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> −30.1、DP3 −50.2 点），而 Hard 用的正是训练分布内的同类随机化。如果连同分布的随机化都会造成这么大跌幅，那么分布外的偏移会怎样是没有数据支撑的。缺的关键证据是一组<strong>与随机化轴正交</strong>的真机测试：改变相机内参、改用反光或透明物体、引入控制延迟或人为遮挡。目前唯一超出五轴的措施是给仿真相机位姿加了 1 cm 以内的扰动，量级很小。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>不需要真机，也不需要重跑 10 万条轨迹。一周内在开源仿真器上即可检验「随机化的收益是否只在同轴偏移上成立」。</p><ul><li><strong>数据与代码</strong>：官方开源的数据生成器与预采集数据集，取 5 个任务、Aloha AgileX 本体、RDT 骨干。</li><li><strong>实现</strong>：训练侧两组——(a) 干净数据，(b) 论文的五轴随机化数据，规模对齐。评测侧四组——(i) Easy；(ii) 论文的 Hard（五轴同轴）；(iii) <strong>正交轴</strong>：只改相机内参与视角（超出 1 cm 的位姿扰动，例如 ±10° 俯仰）；(iv) 只改物体材质属性（提高镜面反射率、加入半透明材质），保持背景/光照/杂物/桌高/语言全部为训练时见过的配置。</li><li><strong>测量</strong>：每组 100 次 rollout 的成功率，以及 (b) 相对 (a) 在四种评测下各自的增益。</li><li><strong>判据</strong>：论文的隐含 claim 要求 (b) 在 (ii)(iii)(iv) 上都优于 (a)。若增益只在 (ii) 上出现、在 (iii)(iv) 上归零甚至为负，则「域随机化带来通用鲁棒性」应收窄为「域随机化带来对被随机化那些轴的鲁棒性」，这会显著改变该数据集的使用建议。</li></ul><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>最有力的攻击针对真机结论的报告方式：<strong>摘要的 367% 与 228% 都来自 16 个格子里基线最低的那一格（9.0%）</strong>，而在这种低基数下相对提升会被机械放大。同一张表按四配置平均的相对提升是约 143%，按绝对点数是 +24.4。而且这些成绩是 4 个任务 × 4 种配置 × 每格 50 次 rollout（由 22.0%、12.0% 这类 2% 的粒度可推断每格试验数为 50）在<strong>单一真机平台</strong>（COBOT-Magic）上取得的，而合成数据侧的策略骨干只有 RDT 一种。</p><p>具体的反例实验：把 10 条干净真机演示换成 10 条<strong>在杂乱场景与变化光照下采集的</strong>真机演示（采集成本相同），再与「10 条干净 + 1,000 条合成」比较。这个对照直接检验一个替代解释——增益是否只是「训练分布里出现了非干净场景」这件事本身，而与它来自仿真还是真机、来自 1,000 条还是 10 条无关。论文当前的所有真机对照里，「有无杂乱/光照多样性」与「有无合成数据」是完全共线的。</p><p>第二条攻击针对基准的构造：Hard 档的随机化参数与训练数据生成用的是同一套代码。这意味着一个把随机化轴当作可辨识变量去建模的策略（例如显式估计光照与背景再做归一化）会在 Hard 上拿到不成比例的收益，而这种收益在真实世界不会兑现。DP3 从 Easy 55.2 塌到 Hard 5.0 已经暗示 Hard 档的难度主要来自视觉外观而非任务本身——作者自己也承认 DP3 的 Easy 成绩部分来自仿真里完美的点云与干净的背景分割。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限。</strong> 当前的随机化是<strong>开环且均匀</strong>的：五个轴各自在预设范围里独立采样，与策略当前的弱点无关。结果是大量算力花在策略早已鲁棒的配置上，而真正致命的组合（例如与目标物同色的背景 + 侧光 + 特定桌高）只被稀疏地覆盖到。基准表里 Easy 到 Hard 的巨大跌幅说明这些致命组合确实存在且未被充分训练。</p><p><strong>新 framing。</strong> 把域随机化从「数据生成的超参数」变成「与策略对抗的一方」，即把数据工厂重新表述为一个双层优化：外层选择随机化参数以最大化当前策略的失败率，内层用这些样本训练策略。这与鲁棒优化里的最坏情况分布（EPOpt 一系已有先例）以及课程学习里的自动难度调度是同一族工具，而本文的基础设施恰好使它可行——因为随机化参数是显式、连续、可程序化控制的，且仿真里的成败判定是自动的。</p><p><strong>第一个实验。</strong> 在 5 个任务上，把五轴随机化参数化成一个低维向量（干扰物数量、背景纹理的与目标物色距、光照色温与方位、桌高偏移、指令模板 ID），用 CEM 或贝叶斯优化在每个训练阶段搜索使当前 RDT checkpoint 失败率最高的参数区域，按 50% 对抗样本 + 50% 均匀样本混合采数据，与等量的纯均匀随机化对照。测量：Hard 档成功率，以及 §10 中三个正交轴上的成功率。若对抗式采样能在<strong>同等数据量</strong>下把 Hard 从 13.7% 明显推高，并且在正交轴上也不落后，那么「数据工厂应该知道策略当前弱在哪里」就获得了第一份实证支持——这会把 RoboTwin 从一个静态数据集变成一个与训练过程耦合的在线组件。</p>',55)])])}const d=a(l,[["render",e]]);export{g as __pageData,d as default};
